prompt:
Crie um componente Progress para um projeto React + Tailwind CSS com shadcn/ui (estilo "New York", acessível via Radix UI).

Alternativa recomendada (registro oficial open source, licença MIT): instale direto com o CLI shadcn:

npx shadcn add progress

Documentação oficial: https://ui.shadcn.com/docs/components/progress

Implementação de referência (MIT — shadcn/ui):

"use client"

import * as React from "react"
import { cn } from "cn"
import { Progress as ProgressPrimitive } from "radix-ui"

function Progress({
  className,
  value,
  ...props
}: React.ComponentProps<typeof ProgressPrimitive.Root>) {
  return (
    <ProgressPrimitive.Root
      data-slot="progress"
      className={cn(
        "relative h-2 w-full overflow-hidden rounded-full bg-primary/20",
        className
      )}
      {...props}
    >
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className="h-full w-full flex-1 bg-primary transition-all"
        style={{ transform: `translateX(-${100 - (value || 0)}%)` }}
      />
    </ProgressPrimitive.Root>
  )
}

export { Progress }
